import pandas as pd

df = pd.read_excel('irs_soi_individual_returns_by_state_us.xlsx', sheet_name='Sheet1', header=None)
col_idx = None
for col in range(2, 12):
    if '$1,000,000 or more' in str(df.iloc[4, col]):
        col_idx = col
        break
for idx, val in df[0].items():
    if 'Salaries and wages' in str(val):
        amount_row = idx + 1
        break
result = int(df.iloc[amount_row, col_idx])
